mapper.select:
SELECT m.*
FROM milestone m
WHERE milestone_seq = #{milestoneSeq}

SELECT m.*
FROM milestone m
WHERE goal_seq    = #{goalSeq}
  AND status      = 'LOCKED'
  AND target_weight >= #{currentWeight}
ORDER BY sort_order

mapper.delete:
DELETE FROM milestone
WHERE goal_seq = #{goalSeq}
  AND status   = 'LOCKED'

mapper.update:
UPDATE milestone
SET photo_seq = #{photoSeq}
WHERE milestone_seq = #{milestoneSeq}
